package dev.mesbase.system.dto;
@com.fasterxml.jackson.annotation.JsonIgnoreProperties({"senderId","senderName","senderNick","recipientName","recipientNick","processTime","status","deletedFlag","attr1","attr2","attr3","attr4","createBy","createTime","updateBy","updateTime","params"})
public record MessageForm(Long messageId,String messageType,String messageLevel,String messageTitle,String messageContent,Long recipientId,String callBack,String remark){public dev.mesbase.system.domain.SysMessage toEntity(){var m=new dev.mesbase.system.domain.SysMessage();m.setMessageId(messageId);m.setMessageType(messageType);m.setMessageLevel(messageLevel);m.setMessageTitle(messageTitle);m.setMessageContent(messageContent);m.setRecipientId(recipientId);m.setCallBack(callBack);m.setRemark(remark);return m;}}
